import { useEffect, useRef, type ReactNode } from 'react';
import { SessionContext } from '../hooks/useSessionId';
import { generateUUID } from '../utils/uuid';

export function SessionProvider({ children }: { children: ReactNode }) {
  const sessionIdRef = useRef<string>(generateUUID());

  useEffect(() => {
    const sessionId = sessionIdRef.current;

    const interval = setInterval(() => {
      fetch('/api/heartbeat', {
        method: 'POST',
        headers: { 'X-Session-ID': sessionId },
        keepalive: true,
      }).catch(() => {});
    }, 30_000);

    const handleBeforeUnload = () => {
      // Send session ID in the request body instead of URL to avoid leaking it in logs
      const body = new Blob(
        [JSON.stringify({ session_id: sessionId })],
        { type: 'application/json' },
      );
      navigator.sendBeacon('/api/session/cleanup', body);
    };

    window.addEventListener('beforeunload', handleBeforeUnload);

    return () => {
      clearInterval(interval);
      window.removeEventListener('beforeunload', handleBeforeUnload);
    };
  }, []);

  return (
    <SessionContext.Provider value={sessionIdRef.current}>
      {children}
    </SessionContext.Provider>
  );
}

from fastapi import APIRouter, Header, Request, Response

from app.session_manager import session_manager

router = APIRouter(prefix="/api", tags=["session"])


@router.post("/heartbeat")
async def heartbeat(x_session_id: str = Header(...)):
    found = session_manager.touch(x_session_id)
    if not found:
        return Response(status_code=404)
    return {"ok": True}


@router.post("/session/cleanup")
async def cleanup_session(
    request: Request,
    x_session_id: str | None = Header(None),
):
    # Accept session_id from: header, JSON body, or query param (legacy).
    effective_id = x_session_id
    if not effective_id:
        try:
            body = await request.json()
            effective_id = body.get("session_id")
        except Exception:
            pass
    if not effective_id:
        effective_id = request.query_params.get("session_id")
    if effective_id:
        session_manager.destroy(effective_id)
    return {"ok": True}

import logging
import os
import threading
from dataclasses import dataclass, field
from datetime import datetime, timedelta, timezone

from app.database import Database

logger = logging.getLogger(__name__)


@dataclass
class SessionEntry:
    db: Database
    last_seen_at: datetime = field(default_factory=lambda: datetime.now(timezone.utc))


class SessionManager:
    def __init__(self) -> None:
        self._sessions: dict[str, SessionEntry] = {}
        self._lock = threading.Lock()

    def get_or_create(self, session_id: str) -> Database:
        with self._lock:
            if session_id not in self._sessions:
                logger.info("Creating new session: %s", session_id)
                db_path = f"/tmp/duckdb-data-agent-{session_id}.duckdb"
                self._sessions[session_id] = SessionEntry(db=Database(db_path))
            else:
                self._sessions[session_id].last_seen_at = datetime.now(timezone.utc)
            return self._sessions[session_id].db

    def touch(self, session_id: str) -> bool:
        with self._lock:
            if session_id not in self._sessions:
                return False
            self._sessions[session_id].last_seen_at = datetime.now(timezone.utc)
            return True

    def destroy(self, session_id: str, delete_file: bool = True) -> None:
        with self._lock:
            entry = self._sessions.pop(session_id, None)
        if entry is None:
            return
        db_path = entry.db.db_path
        try:
            entry.db.conn.close()
        except Exception:
            pass
        if delete_file and db_path != ":memory:":
            for path in [db_path, db_path + ".wal"]:
                try:
                    os.remove(path)
                except FileNotFoundError:
                    pass
        logger.info("Destroyed session: %s (delete_file=%s)", session_id, delete_file)

    def cleanup_stale(self, ttl_seconds: int = 300) -> int:
        cutoff = datetime.now(timezone.utc) - timedelta(seconds=ttl_seconds)
        with self._lock:
            stale = [
                sid for sid, entry in self._sessions.items()
                if entry.last_seen_at < cutoff
            ]
        for sid in stale:
            self.destroy(sid, delete_file=False)
        return len(stale)


session_manager = SessionManager()

