from fastapi import APIRouter, Query
from fastapi.responses import JSONResponse
from pydantic import BaseModel

from app.memory_store import memory_store

router = APIRouter(prefix="/api/conversations", tags=["conversations"])


class CreateConversationRequest(BaseModel):
    user_id: str = "default"
    title: str | None = None


class UpdateConversationRequest(BaseModel):
    title: str


@router.get("")
async def list_conversations(user_id: str = Query("default"), limit: int = Query(50), offset: int = Query(0)):
    return memory_store.list_conversations(user_id=user_id, limit=limit, offset=offset)


@router.post("")
async def create_conversation(request: CreateConversationRequest):
    return memory_store.create_conversation(user_id=request.user_id, title=request.title)


@router.get("/{conversation_id}")
async def get_conversation(conversation_id: str):
    conv = memory_store.get_conversation(conversation_id)
    if conv is None:
        return JSONResponse(status_code=404, content={"error": "Conversation not found"})
    return conv


@router.put("/{conversation_id}")
async def update_conversation(conversation_id: str, request: UpdateConversationRequest):
    if not memory_store.update_conversation(conversation_id, request.title):
        return JSONResponse(status_code=404, content={"error": "Conversation not found"})
    return {"status": "ok"}


@router.delete("/{conversation_id}")
async def delete_conversation(conversation_id: str):
    if not memory_store.delete_conversation(conversation_id):
        return JSONResponse(status_code=404, content={"error": "Conversation not found"})
    return {"status": "ok"}

from fastapi import APIRouter, Header, Request, Response

from app.session_manager import session_manager

router = APIRouter(prefix="/api", tags=["session"])


@router.post("/heartbeat")
async def heartbeat(x_session_id: str = Header(...)):
    found = session_manager.touch(x_session_id)
    if not found:
        return Response(status_code=404)
    return {"ok": True}


@router.post("/session/cleanup")
async def cleanup_session(
    request: Request,
    x_session_id: str | None = Header(None),
):
    # Accept session_id from: header, JSON body, or query param (legacy).
    effective_id = x_session_id
    if not effective_id:
        try:
            body = await request.json()
            effective_id = body.get("session_id")
        except Exception:
            pass
    if not effective_id:
        effective_id = request.query_params.get("session_id")
    if effective_id:
        session_manager.destroy(effective_id)
    return {"ok": True}

