488→              currentTextRef.current = '';
489→            }
490→            setMessages((prev) =>
491→              prev.map((m) =>
492→                m.id === assistantId
493→                  ? { ...m, isStreaming: false, currentPhase: undefined, segments: [...segmentsRef.current] }
494→                  : m
